window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-188475e37f88104c"]={"versions": [{"id": "FIG-188475e37f88104c", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des senderseitigen Transformer-Kaskadenablaufs in der AUTOSAR Classic Platform. Das Diagramm spezifiziert den Kontrollfluss bei der Datenübertragung einer Software-Komponente über die RTE unter Einbindung einer Transformationskette aus SOME/IP-Transformer und E2E-Transformer vor der Übergabe an nachgelagerte Kommunikationsschichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Teilnehmende Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>SWC</code>: Anwendungs-Software-Komponente als Sender.</li>\n<li><code>«module» Rte</code>: AUTOSAR Run-Time Environment als Vermittlungsschicht.</li>\n<li><code>SomeIpXf</code>: SOME/IP-Transformer zur Serialisierung/Transformation.</li>\n<li><code>E2EXf</code>: E2E-Transformer zur Absicherung der Datenübertragung.</li>\n<li><code>«module» E2E</code>: AUTOSAR E2E Library zur Durchführung der Prüfsummen- und Zählerberechnung.</li>\n<li><code>«module» Com</code>: AUTOSAR Kommunikationsmodul (als unbeteiligte bzw. nachgelagerte Lebenslinie dargestellt).</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>Rte_Write_p_d( ) :ret</code>: API-Aufruf der <code>SWC</code> an die <code>Rte</code> mit expliziter Rückgabe.</li>\n<li><code>SomeIpXf_&lt;transformerId&gt;( )</code>: Aufruf des SOME/IP-Transformers durch die <code>Rte</code>.</li>\n<li><code>E2EXf_&lt;transformreId&gt;( )</code>: Aufruf des E2E-Transformers durch die <code>Rte</code>.</li>\n<li><code>E2E_Protect( )</code>: Aufruf der E2E-Bibliotheksfunktion durch <code>E2EXf</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchroner Kontrollfluss von links nach rechts:</p>\n<ol class=\"fig-list\">\n<li><code>SWC</code> initiiert den Sendevorgang durch synchronen Aufruf von <code>Rte_Write_p_d( ) :ret</code> an die <code>Rte</code>.</li>\n<li>Während der Ausführungsphase der <code>Rte</code> ruft diese synchron <code>SomeIpXf_&lt;transformerId&gt;( )</code> auf; die Ausführung im <code>SomeIpXf</code> wird abgeschlossen und der Kontrollfluss kehrt zur <code>Rte</code> zurück.</li>\n<li>Anschließend ruft die <code>Rte</code> synchron <code>E2EXf_&lt;transformreId&gt;( )</code> auf.</li>\n<li>Aus dem Aktivierungsbalken von <code>E2EXf</code> heraus erfolgt der synchrone Aufruf <code>E2E_Protect( )</code> an das Bibliotheksmodul <code>E2E</code>.</li>\n<li>Nach Abschluss der Schutzfunktion kehrt der Kontrollfluss kaskadiert über <code>E2EXf</code> zur <code>Rte</code> zurück. Die Lebenslinie <code>«module» Com</code> wird im dargestellten Sequenzausschnitt nicht aufgerufen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt verbindlich die Reihenfolge der Transformer-Ausführung bei einer Sender-Kaskade aus Serialisierung gefolgt von E2E-Absicherung. Die RTE steuert die Transformer nacheinander an: Zuerst serialisiert der SOME/IP-Transformer die Nutzdaten, danach schützt der E2E-Transformer den bereits transformierten Datenstrom mittels der E2E-Bibliothek (<code>E2E_Protect</code>). Entwickler müssen beachten, dass der Bezeichner <code>E2EXf_&lt;transformreId&gt;()</code> im Diagramm einen Schreibfehler enthält (<code>transformreId</code> statt <code>transformerId</code>).</p>"}, {"id": "FIG-ef79557de777e3f1", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des senderseitigen Transformer-Kaskadenablaufs in der AUTOSAR Classic Platform. Das Diagramm spezifiziert den Kontrollfluss bei der Datenübertragung einer Software-Komponente über die RTE unter Einbindung einer Transformationskette aus SOME/IP-Transformer und E2E-Transformer vor der Übergabe an nachgelagerte Kommunikationsschichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Teilnehmende Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>SWC</code>: Anwendungs-Software-Komponente als Sender.</li>\n<li><code>«module» Rte</code>: AUTOSAR Run-Time Environment als Vermittlungsschicht.</li>\n<li><code>SomeIpXf</code>: SOME/IP-Transformer zur Serialisierung/Transformation.</li>\n<li><code>E2EXf</code>: E2E-Transformer zur Absicherung der Datenübertragung.</li>\n<li><code>«module» E2E</code>: AUTOSAR E2E Library zur Durchführung der Prüfsummen- und Zählerberechnung.</li>\n<li><code>«module» Com</code>: AUTOSAR Kommunikationsmodul (als unbeteiligte bzw. nachgelagerte Lebenslinie dargestellt).</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>Rte_Write_p_d( ) :ret</code>: API-Aufruf der <code>SWC</code> an die <code>Rte</code> mit expliziter Rückgabe.</li>\n<li><code>SomeIpXf_&lt;transformerId&gt;( )</code>: Aufruf des SOME/IP-Transformers durch die <code>Rte</code>.</li>\n<li><code>E2EXf_&lt;transformreId&gt;( )</code>: Aufruf des E2E-Transformers durch die <code>Rte</code>.</li>\n<li><code>E2E_Protect( )</code>: Aufruf der E2E-Bibliotheksfunktion durch <code>E2EXf</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchroner Kontrollfluss von links nach rechts:</p>\n<ol class=\"fig-list\">\n<li><code>SWC</code> initiiert den Sendevorgang durch synchronen Aufruf von <code>Rte_Write_p_d( ) :ret</code> an die <code>Rte</code>.</li>\n<li>Während der Ausführungsphase der <code>Rte</code> ruft diese synchron <code>SomeIpXf_&lt;transformerId&gt;( )</code> auf; die Ausführung im <code>SomeIpXf</code> wird abgeschlossen und der Kontrollfluss kehrt zur <code>Rte</code> zurück.</li>\n<li>Anschließend ruft die <code>Rte</code> synchron <code>E2EXf_&lt;transformreId&gt;( )</code> auf.</li>\n<li>Aus dem Aktivierungsbalken von <code>E2EXf</code> heraus erfolgt der synchrone Aufruf <code>E2E_Protect( )</code> an das Bibliotheksmodul <code>E2E</code>.</li>\n<li>Nach Abschluss der Schutzfunktion kehrt der Kontrollfluss kaskadiert über <code>E2EXf</code> zur <code>Rte</code> zurück. Die Lebenslinie <code>«module» Com</code> wird im dargestellten Sequenzausschnitt nicht aufgerufen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt verbindlich die Reihenfolge der Transformer-Ausführung bei einer Sender-Kaskade aus Serialisierung gefolgt von E2E-Absicherung. Die RTE steuert die Transformer nacheinander an: Zuerst serialisiert der SOME/IP-Transformer die Nutzdaten, danach schützt der E2E-Transformer den bereits transformierten Datenstrom mittels der E2E-Bibliothek (<code>E2E_Protect</code>). Entwickler müssen beachten, dass der Bezeichner <code>E2EXf_&lt;transformreId&gt;()</code> im Diagramm einen Schreibfehler enthält (<code>transformreId</code> statt <code>transformerId</code>).</p>"}, {"id": "FIG-e6271c93730e0e17", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des senderseitigen Transformer-Kaskadenablaufs in der AUTOSAR Classic Platform. Das Diagramm spezifiziert den Kontrollfluss bei der Datenübertragung einer Software-Komponente über die RTE unter Einbindung einer Transformationskette aus SOME/IP-Transformer und E2E-Transformer vor der Übergabe an nachgelagerte Kommunikationsschichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Teilnehmende Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>SWC</code>: Anwendungs-Software-Komponente als Sender.</li>\n<li><code>«module» Rte</code>: AUTOSAR Run-Time Environment als Vermittlungsschicht.</li>\n<li><code>SomeIpXf</code>: SOME/IP-Transformer zur Serialisierung/Transformation.</li>\n<li><code>E2EXf</code>: E2E-Transformer zur Absicherung der Datenübertragung.</li>\n<li><code>«module» E2E</code>: AUTOSAR E2E Library zur Durchführung der Prüfsummen- und Zählerberechnung.</li>\n<li><code>«module» Com</code>: AUTOSAR Kommunikationsmodul (als unbeteiligte bzw. nachgelagerte Lebenslinie dargestellt).</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;( [&lt;instance&gt;], &lt;data&gt; , [&lt;transformerError&gt;])</code>: Generische API der <code>Rte</code> für den Sendeaufruf durch die <code>SWC</code> mit optionaler Instanzkennung, Nutzdaten und optionalem Zeiger zur Rückgabe von Transformer-Fehlern.</li>\n<li><code>SomeIpXf_&lt;transformerId&gt;( )</code>: Aufruf des SOME/IP-Transformers durch die <code>Rte</code>.</li>\n<li><code>E2EXf_&lt;transformreId&gt;( )</code>: Aufruf des E2E-Transformers durch die <code>Rte</code>.</li>\n<li><code>E2E_Protect( )</code>: Aufruf der E2E-Bibliotheksfunktion durch <code>E2EXf</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchroner Kontrollfluss von links nach rechts:</p>\n<ol class=\"fig-list\">\n<li><code>SWC</code> initiiert den Sendevorgang durch Aufruf von <code>Rte_Write_&lt;p&gt;_&lt;o&gt;( [&lt;instance&gt;], &lt;data&gt; , [&lt;transformerError&gt;])</code> an die <code>Rte</code>.</li>\n<li>Während der Ausführungsphase der <code>Rte</code> ruft diese synchron <code>SomeIpXf_&lt;transformerId&gt;( )</code> auf; die Ausführung im <code>SomeIpXf</code> wird abgeschlossen und der Kontrollfluss kehrt zur <code>Rte</code> zurück.</li>\n<li>Anschließend ruft die <code>Rte</code> synchron <code>E2EXf_&lt;transformreId&gt;( )</code> auf.</li>\n<li>Aus dem Aktivierungsbalken von <code>E2EXf</code> heraus erfolgt der synchrone Aufruf <code>E2E_Protect( )</code> an das Bibliotheksmodul <code>E2E</code>.</li>\n<li>Nach Abschluss der Schutzfunktion kehrt der Kontrollfluss kaskadiert über <code>E2EXf</code> zur <code>Rte</code> zurück. Die Lebenslinie <code>«module» Com</code> wird im dargestellten Sequenzausschnitt nicht aufgerufen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt verbindlich die Reihenfolge der Transformer-Ausführung bei einer Sender-Kaskade aus Serialisierung gefolgt von E2E-Absicherung. Die RTE steuert die Transformer nacheinander an: Zuerst serialisiert der SOME/IP-Transformer die Nutzdaten, danach schützt der E2E-Transformer den bereits transformierten Datenstrom mittels der E2E-Bibliothek (<code>E2E_Protect</code>). Entwickler müssen beachten, dass die RTE-Schnittstelle die Rückgabe bzw. Weitergabe von Transformer-Fehlern über das optionale Argument <code>[&lt;transformerError&gt;]</code> vorsieht. Zudem enthält der Funktionsname <code>E2EXf_&lt;transformreId&gt;()</code> im Diagramm weiterhin den Schreibfehler (<code>transformreId</code> statt <code>transformerId</code>).</p>"}, {"id": "FIG-935458506d2934c4", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des senderseitigen Transformer-Kaskadenablaufs in der AUTOSAR Classic Platform. Das Diagramm spezifiziert den Kontrollfluss bei der Datenübertragung einer Software-Komponente über die RTE unter Einbindung einer Transformationskette aus SOME/IP-Transformer und E2E-Transformer vor der Übergabe an nachgelagerte Kommunikationsschichten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Teilnehmende Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>SWC</code>: Anwendungs-Software-Komponente als Sender.</li>\n<li><code>«module» Rte</code>: AUTOSAR Run-Time Environment als Vermittlungsschicht.</li>\n<li><code>SomeIpXf</code>: SOME/IP-Transformer zur Serialisierung/Transformation.</li>\n<li><code>E2EXf</code>: E2E-Transformer zur Absicherung der Datenübertragung.</li>\n<li><code>«module» E2E</code>: AUTOSAR E2E Library zur Durchführung der Prüfsummen- und Zählerberechnung.</li>\n<li><code>«module» Com</code>: AUTOSAR Kommunikationsmodul (als unbeteiligte bzw. nachgelagerte Lebenslinie dargestellt).</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;( [&lt;instance&gt;], &lt;data&gt; , [&lt;transformerError&gt;])</code>: Generische API der <code>Rte</code> für den Sendeaufruf durch die <code>SWC</code> mit optionaler Instanzkennung, Nutzdaten und optionalem Zeiger zur Rückgabe von Transformer-Fehlern.</li>\n<li><code>SomeIpXf_&lt;transformerId&gt;( )</code>: Aufruf des SOME/IP-Transformers durch die <code>Rte</code>.</li>\n<li><code>E2EXf_&lt;transformreId&gt;( )</code>: Aufruf des E2E-Transformers durch die <code>Rte</code>.</li>\n<li><code>E2E_Protect( )</code>: Aufruf der E2E-Bibliotheksfunktion durch <code>E2EXf</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchroner Kontrollfluss von links nach rechts:</p>\n<ol class=\"fig-list\">\n<li><code>SWC</code> initiiert den Sendevorgang durch Aufruf von <code>Rte_Write_&lt;p&gt;_&lt;o&gt;( [&lt;instance&gt;], &lt;data&gt; , [&lt;transformerError&gt;])</code> an die <code>Rte</code>.</li>\n<li>Während der Ausführungsphase der <code>Rte</code> ruft diese synchron <code>SomeIpXf_&lt;transformerId&gt;( )</code> auf; die Ausführung im <code>SomeIpXf</code> wird abgeschlossen und der Kontrollfluss kehrt zur <code>Rte</code> zurück.</li>\n<li>Anschließend ruft die <code>Rte</code> synchron <code>E2EXf_&lt;transformreId&gt;( )</code> auf.</li>\n<li>Aus dem Aktivierungsbalken von <code>E2EXf</code> heraus erfolgt der synchrone Aufruf <code>E2E_Protect( )</code> an das Bibliotheksmodul <code>E2E</code>.</li>\n<li>Nach Abschluss der Schutzfunktion kehrt der Kontrollfluss kaskadiert über <code>E2EXf</code> zur <code>Rte</code> zurück. Die Lebenslinie <code>«module» Com</code> wird im dargestellten Sequenzausschnitt nicht aufgerufen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt verbindlich die Reihenfolge der Transformer-Ausführung bei einer Sender-Kaskade aus Serialisierung gefolgt von E2E-Absicherung. Die RTE steuert die Transformer nacheinander an: Zuerst serialisiert der SOME/IP-Transformer die Nutzdaten, danach schützt der E2E-Transformer den bereits transformierten Datenstrom mittels der E2E-Bibliothek (<code>E2E_Protect</code>). Entwickler müssen beachten, dass die RTE-Schnittstelle die Rückgabe bzw. Weitergabe von Transformer-Fehlern über das optionale Argument <code>[&lt;transformerError&gt;]</code> vorsieht. Zudem enthält der Funktionsname <code>E2EXf_&lt;transformreId&gt;()</code> im Diagramm weiterhin den Schreibfehler (<code>transformreId</code> statt <code>transformerId</code>).</p>"}], "trans": [{"from": "FIG-188475e37f88104c", "to": "FIG-ef79557de777e3f1", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ef79557de777e3f1", "to": "FIG-e6271c93730e0e17", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Signatur des RTE-Sendeaufrufs von <code>SWC</code> an <code>Rte</code>: Ersetzung von <code>Rte_Write_p_d( ) :ret</code> durch <code>Rte_Write_&lt;p&gt;_&lt;o&gt;( [&lt;instance&gt;], &lt;data&gt; , [&lt;transformerError&gt;])</code> unter Einführung der generischen Platzhalter <code>&lt;p&gt;</code> (Port), <code>&lt;o&gt;</code> (Data Element/Operation) sowie der formalen Parameter <code>[&lt;instance&gt;]</code>, <code>&lt;data&gt;</code> und des optionalen Ausgabeparameters <code>[&lt;transformerError&gt;]</code>.</li>\n</ul>"}, {"from": "FIG-e6271c93730e0e17", "to": "FIG-935458506d2934c4", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
